/* Huyết Lệ Thôn — lồng tiếng (ElevenLabs, eleven_v4). Tạo bởi tools/build_vo.py. */
(function(H){H.VO={dur:{"C00": 2.92, "C01": 2.52, "C02": 1.69, "C03": 6.7, "C04": 4.72, "C05": 6.16, "C06": 3.17, "C07": 4.5, "C08": 2.74, "C09": 3.24, "C10": 4.39, "C11": 2.16, "C12": 4.68, "C13": 2.7, "C14": 4.03, "C15": 0.9, "C16": 5.29, "C17": 5.9, "C18": 6.41, "C19": 4.86, "C20": 3.96, "C21": 6.16, "C22": 3.38, "C23": 6.19, "C24": 4.61, "C25": 5.29, "C26": 2.45, "C27": 2.66, "C28": 7.06, "C29": 6.19, "C30": 6.95, "C31": 3.89, "C32": 5.47, "C33": 6.95, "C34": 7.27, "C35": 3.46, "L_start": 4.57, "L_gotCamera": 2.12, "L_gateLocked": 4.07, "L_gateOpen": 3.92, "L_needCrank": 5.58, "L_crankPlaced": 2.48, "L_ambush": 2.3, "L_stunned": 3.89, "L_manorLocked": 2.99, "L_manorOpen": 3.2, "L_safeHint": 5.9, "L_gotScroll": 4.64, "L_graveyard": 3.92, "L_allOfferings": 2.34, "L_templeLocked": 4.43, "L_templeOpen": 2.66, "L_altarNeed": 2.52, "L_lowBattery": 1.48, "L_noFilm": 1.91, "L_ringFound": 5.22, "L_tuanAfter": 3.96, "L_haAfter": 3.85, "L_offering2": 1.44, "L_offering1": 1.51, "L_photo0": 2.3, "L_photo1": 2.09, "L_photo2": 2.45, "E_true0": 1.37, "E_true1": 7.7, "E_true2": 5.44, "E_true3": 7.06, "E_true4": 7.7, "E_true5": 7.16, "E_true6": 4.93, "E_bad0": 1.84, "E_bad1": 5.4, "E_bad2": 2.88, "E_bad3": 5.18, "E_bad4": 3.02, "E_bad5": 6.16, "E_bad6": 2.16, "E_best1": 7.2, "E_best2": 9.83, "E_best3": 2.52, "E_best4": 8.1, "E_best5": 9.07, "E_best6": 11.16, "E_best7": 6.16, "M00": 6.7, "M01": 3.31, "M02": 4.57, "M03": 2.56, "M10": 3.89, "M11": 4.36, "M12": 5.69, "M13": 1.87, "M20": 3.92, "M21": 3.02, "M22": 3.06, "M23": 1.98},t:{"Ba giờ trước khi vạt núi sạt xuống.": "C00", "Chị Linh ơi, bản đồ có vẽ lối này đâu?": "C01", "Cứ đi đi. Sắp tới rồi.": "C02", "Mùa thu năm 1994. Bão số 6 cuốn mất con đường sau lưng chúng tôi.": "C03", "Linh, Tuấn, Hà... mình lạc cả ba ở đâu đó giữa rừng tre này.": "C04", "Linh bảo trên này có một ngôi làng bỏ hoang đáng để chụp. Bản đồ thì chẳng vẽ gì.": "C05", "Máy ảnh của ông nội... mình đánh rơi nó khi chạy.": "C06", "Sợi xích tự tuột khỏi cổng, như thể chỉ chờ đúng con số ấy.": "C07", "...Hà? Hà, phải em không?": "C08", "Đừng tắt đèn, Minh ạ... chị ấy đi theo tiếng chân...": "C09", "Ba lô của Tuấn. Đồng hồ đeo tay dừng ở 0 giờ 49.": "C10", "Dây thừng thả xuống giếng... TUẤN!": "C11", "...đừng kéo tao lên vội... dưới này có hai người, Minh ạ... họ nắm tay nhau...": "C12", "Gương đồng... và một chiếc chìa khoá.": "C13", "Sợi dây tời bỗng căng lên. Có thứ gì đó đang trèo theo.": "C14", "CHẠY!": "C15", "Ta, Đoàn Văn Khải, viết bằng máu mình vì mực không chịu ăn giấy nữa.": "C16", "Thằng Khang con ta không chết vì dịch. Nó định lên huyện tố cha nó bán thóc phát chẩn.": "C17", "Ta chỉ sai tuần đinh giam nó. Chúng nặng tay. Trước lúc trời sáng, ta thả con ta xuống giếng.": "C18", "Rồi ta cần một con yêu nữ, để cả làng khỏi hỏi vì sao nước giếng đỏ.": "C19", "Người làm chứng điểm chỉ: Phó Văn Bảy... Trần Sửu.": "C20", "Họ Đoàn. Họ Phó. Họ Trần. ...Linh. Mình. Tuấn.": "C21", "Đừng lại gần! ...Minh? Là anh thật à?": "C22", "Chị ấy không hại em. Chị ấy đứng ngoài cửa suốt, mỗi lần mấy cái bóng cầm đuốc đi qua.": "C23", "Chị ấy chỉ đuổi anh, anh Tuấn... và chị Linh. Sao lại đúng ba người?": "C24", "Em không ra đâu. Cầm lấy cuộn băng này — của chị Linh. Chị ấy dặn đừng cho anh nghe trước khi tới Đình.": "C25", "...Em nghe rồi, phải không Hà?": "C26", "Cậu có đôi mắt của thằng Lộc cháu tôi.": "C27", "Sáu mươi năm trước nó dẫn đường cho đoàn đo đạc Tây lên đây. Chỉ mình nó ra được — vì nó dám chụp thẳng mặt nàng.": "C28", "Cái máy ảnh ấy giờ đeo trên cổ cậu. Làng không gọi bừa đâu. Làng gọi con cháu về trả nợ.": "C29", "Còn một thứ tôi không dám chôn: nhẫn bạc của cậu Khang. Tôi giấu ở miếu nhỏ dưới gốc đa. Soi gương mà tìm.": "C30", "Gọi đúng tên thì nàng đi. Nhưng dưới giếng có hai người.": "C31", "Đình làng, đêm rằm tháng Bảy. Then cửa đã cài — từ bên ngoài.": "C32", "Lệ ơi... mẹ không oán ai. Mẹ chỉ xin một người — một người thôi — nhớ lấy tên con.": "C33", "Bà không nguyền rủa ai cả. Lời nguyền là của những kẻ đứng ngoài, nghe hết, và không rút then.": "C34", "Minh... đừng vào. Chính em đưa mọi người tới đây.": "C35", "Minh: Đèn pin vẫn còn. [F] để bật. Máy ảnh... mình đánh rơi đâu đó trên lối mòn này.": "L_start", "Minh: Máy ảnh của mình. Vẫn còn phim. [C] để nâng máy, chuột trái để chụp.": "L_gotCamera", "Minh: Khoá số bốn vòng. Phải có manh mối quanh đây... tấm bia đá kia?": "L_gateLocked", "Minh: Xích tự tuột ra. Như thể nó chỉ chờ mình nói đúng năm.": "L_gateOpen", "Minh: Tời giếng mất tay quay. Tuấn có nhắc... ai đó đã giấu nó trong nhà.": "L_needCrank", "Minh: Vừa khít. Nào... kéo lên.": "L_crankPlaced", "Minh: Cái gì đang trèo lên theo sợi dây—— CHẠY! Nâng máy ảnh [C] chụp thẳng mặt nó, hoặc trốn vào tủ [E]!": "L_ambush", "Minh: Đèn flash làm nó tan đi... nhưng nó sẽ trở lại.": "L_stunned", "Minh: Khoá đồng. Cần chìa khoá của nhà Lý trưởng.": "L_manorLocked", "Minh: Trong này lạnh hơn ngoài mưa. Thử nhìn qua ống ngắm xem...": "L_manorOpen", "Minh: Két ba số. Biên bản ghi: TRÓI — THIÊU — DÌM. Ảnh sẽ cho mình thứ tự.": "L_safeHint", "Minh: Huyết Thư. Lão ta đã tự thú... rồi khoá nó lại suốt một trăm hai mươi năm.": "L_gotScroll", "Minh: Nghĩa địa. Giữ [R] soi gương đồng — vệt sáng trên vành gương chỉ hướng lễ vật.": "L_graveyard", "Minh: Đủ ba lễ vật. Lên Đình thôi.": "L_allOfferings", "Minh: Cửa Đình dán kín bùa. Linh nói cần lời thú tội của kẻ chủ mưu...": "L_templeLocked", "Minh: Bùa tự cháy thành tro khi Huyết Thư đến gần.": "L_templeOpen", "Minh: Đàn Ngũ Hành. Còn thiếu lễ vật.": "L_altarNeed", "Minh: Pin sắp hết...": "L_lowBattery", "Minh: Hết phim rồi.": "L_noFilm", "Minh: Nhẫn bạc. Mặt trong khắc chữ \"Lệ\". Người ấy đã định về đón cô.": "L_ringFound", "Minh: Tuấn còn sống. Nhưng muốn kéo cậu ấy lên thì phải có tay quay.": "L_tuanAfter", "Minh: Hà an toàn — vì Hà không mang họ của ai trong ba người đó.": "L_haAfter", "Minh: Còn 2 lễ vật nữa.": "L_offering2", "Minh: Còn 1 lễ vật nữa.": "L_offering1", "Ảnh 1/3 — TRÓI: trên vách hiện số 3.": "L_photo0", "Ảnh 2/3 — THIÊU: tro xếp thành số 7.": "L_photo1", "Ảnh 3/3 — DÌM: nước nhỏ giọt thành số 5.": "L_photo2", "“Nguyễn Thị Lệ.”": "E_true0", "Ngọn lửa trên đàn chuyển từ đỏ sang trắng. Bảy thước lụa điều rơi khỏi cổ tay nàng, từng vòng một.": "E_true1", "Lần đầu tiên sau một trăm hai mươi năm, có người gọi nàng bằng cái tên mẹ đặt.": "E_true2", "Nàng thôi khóc. Nhưng trước khi tan đi, nàng ngoái nhìn về phía cái giếng — rất lâu.": "E_true3", "Trăng lặn. Mưa tạnh. Dưới gốc đa có hai người nằm thiếp đi: Linh và Hà. Còn thở.": "E_true4", "Tuấn không có ở đó. Đội cứu hộ tìm ba ngày, chỉ thấy một chiếc đồng hồ dừng ở 0 giờ 49.": "E_true5", "Vòng lặp đã đứt. Nhưng dưới giếng vẫn còn một người chưa ai gọi tên.": "E_true6", "Ngọn lửa tắt phụt.": "E_bad0", "Nàng nghiêng đầu nhìn bạn — rất lâu — như nhìn thêm một người làng nữa.": "E_bad1", "“Các người... vẫn gọi ta bằng cái tên ấy.”": "E_bad2", "Cửa Đình đóng sầm. Bên ngoài có tiếng then cài. Rồi tiếng đuốc.": "E_bad3", "Đồng hồ chỉ 0 giờ 49.": "E_bad4", "Mùa thu năm 1994. Cơn bão cuốn trôi con đường sau lưng chúng tôi...": "E_bad5", "Sáu mươi năm một vòng.": "E_bad6", "Bạn đặt chiếc nhẫn bạc lên Đàn Ngũ Hành. “Khang gửi. Anh ấy không bỏ cô. Anh ấy xuống đó trước cô.”": "E_best1", "Ngọn lửa trắng tách làm hai. Từ phía giếng có một bóng người bước vào Đình — ướt sũng, lóng ngóng, như kẻ về muộn một trăm hai mươi năm.": "E_best2", "Lần này không ai cài then.": "E_best3", "Hai cái bóng đi qua bạn, qua ngưỡng cửa, ra sân. Nàng đeo nhẫn. Nàng cười — bạn chưa từng nghĩ khuôn mặt ấy cười được.": "E_best4", "Trăng lặn. Mưa tạnh. Dưới gốc đa có ba người nằm thiếp đi: Linh, Hà, và Tuấn — tay còn nắm sợi dây thừng.": "E_best5", "Sáng hôm sau đội cứu hộ tìm thấy bốn người trên một bãi đất trống. Không có ngôi làng nào ở đó. Chỉ có một cái giếng cạn, và dưới đáy, hai bộ hài cốt nằm quay mặt vào nhau.": "E_best6", "Người ta chôn họ chung một mộ. Bia chỉ khắc hai cái tên. Không có chữ “nương” nào cả.": "E_best7", "Rằm tháng Bảy, năm Giáp Tuất — 1874. Chính đường nhà Lý trưởng.": "M00", "Trói nó lại. Bảy thước lụa điều, cho nó khỏi hoá về.": "M01", "Con sắc thuốc cho con các người... sao không ai nhìn con?": "M02", "Trên vách hiện một con số: 3.": "M03", "Cũng đêm ấy, họ dồn cha mẹ nàng vào trong Đình.": "M10", "Lệ ơi! Đừng nhận! Con không làm gì sai cả!": "M11", "Người gác đình cài then từ bên ngoài. Tay ông ta run tới mức phải cài hai lần.": "M12", "Tro xếp thành con số 7.": "M13", "Họ thả nàng xuống Giếng Cổ lúc 0 giờ 49.": "M20", "Lấp đá lại. Từ nay cấm nhắc tên hai đứa nó.": "M21", "“Hai đứa”...? Biên bản chỉ ghi có một người.": "M22", "Nước nhỏ giọt thành con số 5.": "M23"},d:{"C00": "", "C01": "", "C02": "", "C03": "", "C04": "", "C05": "", "C06": "", "C07": "", "C08": "", "C09": "", "C10": "", "C11": "", "C12": "", "C13": "", "C14": "", "C15": "", "C16": "", "C17": "", "C18": "", "C19": "", "C20": "", "C21": "", "C22": "", "C23": "", "C24": "", "C25": "", "C26": "", "C27": "", "C28": "", "C29": "", "C30": "", "C31": "", "C32": "", "C33": "", "C34": "", "C35": "", "L_start": "", "L_gotCamera": "", "L_gateLocked": "", "L_gateOpen": "", "L_needCrank": "", "L_crankPlaced": "", "L_ambush": "", "L_stunned": "", "L_manorLocked": "", "L_manorOpen": "", "L_safeHint": "", "L_gotScroll": "", "L_graveyard": "", "L_allOfferings": "", "L_templeLocked": "", "L_templeOpen": "", "L_altarNeed": "", "L_lowBattery": "", "L_noFilm": "", "L_ringFound": "", "L_tuanAfter": "", "L_haAfter": "", "L_offering2": "", "L_offering1": "", "L_photo0": "", "L_photo1": "", "L_photo2": "", "E_true0": "", "E_true1": "", "E_true2": "", "E_true3": "", "E_true4": "", "E_true5": "", "E_true6": "", "E_bad0": "", "E_bad1": "", "E_bad2": "", "E_bad3": "", "E_bad4": "", "E_bad5": "", "E_bad6": "", "E_best1": "", "E_best2": "", "E_best3": "", "E_best4": "", "E_best5": "", "E_best6": "", "E_best7": "", "M00": "", "M01": "", "M02": "", "M03": "", "M10": "", "M11": "", "M12": "", "M13": "", "M20": "", "M21": "", "M22": "", "M23": ""}};})(window.HuyetLeThon);
